Below is a **complete, ready-to-copy TypeScript example** that

1. creates an IndexedDB store for vector-tile blobs,
2. registers a `cache://` protocol with **MapLibre GL JS** (`maplibregl.addProtocol` – promise-based, available since v4.0.0),
3. falls back to the network when a tile is not in the cache (and writes the fetched tile back to IndexedDB), and
4. shows a style that references the custom scheme.

You can drop the code into a normal browser project (or a Vite/Next/React app) and it will work with any MapLibre GL JS version ≥ 4.0.0.

---

## 1️⃣ Install the tiny `idb` helper (optional but makes IndexedDB painless)

```bash
npm i idb
# or yarn add idb
```

`idb` gives you a nice Promise-based API and TypeScript typings.

---

## 2️⃣ IndexedDB helper – one table that stores raw MVT bytes

```ts
// src/TileCache.ts
import { openDB, DBSchema, IDBPDatabase } from 'idb';

interface TileCacheDB extends DBSchema {
  /** key = `${z}/${x}/${y}`  (no leading slash) */
  tiles: {
    key: string;
    value: ArrayBuffer; // raw MVT bytes
  };
}

/** Singleton – open the DB once */
let dbPromise: Promise<IDBPDatabase<TileCacheDB>> | null = null;
function getDB() {
  if (!dbPromise) {
    dbPromise = openDB<TileCacheDB>('maplibre-tile-cache', 1, {
      upgrade(db) {
        db.createObjectStore('tiles');
      },
    });
  }
  return dbPromise;
}

/** Store a tile */
export async function putTile(z: number, x: number, y: number, data: ArrayBuffer) {
  const db = await getDB();
  const key = `${z}/${x}/${y}`;
  await db.put('tiles', data, key);
}

/** Retrieve a tile – returns undefined if not cached */
export async function getTile(z: number, x: number, y: number): Promise<ArrayBuffer | undefined> {
  const db = await getDB();
  const key = `${z}/${x}/${y}`;
  return db.get('tiles', key);
}
```

---

## 3️⃣ Register the `cache://` protocol

```ts
// src/registerCacheProtocol.ts
import maplibregl, { RequestParameters, RequestParametersWithUrl } from 'maplibre-gl';
import { getTile, putTile } from './TileCache';

/**
 * Parse a URL of the form  cache://tiles/{z}/{x}/{y}
 * Returns {z,x,y} or throws if the URL does not match.
 */
function parseCacheUrl(url: string): { z: number; x: number; y: number } {
  // Remove the scheme and possible leading slash
  const path = url.replace(/^cache:\/\//, '').replace(/^\/+/, '');
  // Expected: tiles/14/8623/5401
  const parts = path.split('/');
  if (parts.length !== 4 || parts[0] !== 'tiles') {
    throw new Error(`Unexpected cache URL: ${url}`);
  }
  const [z, x, y] = parts.slice(1).map(Number);
  if ([z, x, y].some(Number.isNaN)) {
    throw new Error(`Invalid tile coordinates in ${url}`);
  }
  return { z, x, y };
}

/**
 * The protocol handler.  It must return a Promise that resolves to an object
 * with at least a `data: ArrayBuffer` property.
 *
 * If the tile is not cached we fetch it from the network (you can change the
 * fallback URL pattern) and store it for the next request.
 */
export function registerCacheProtocol() {
  maplibregl.addProtocol('cache', async (params: RequestParameters) => {
    // `params.url` is the full URL that the style asked for.
    const { url } = params as RequestParametersWithUrl;
    const { z, x, y } = parseCacheUrl(url);

    // 1️⃣ Try the IndexedDB cache first
    const cached = await getTile(z, x, y);
    if (cached) {
      // Return the cached bytes – MapLibre will treat it exactly like a network response.
      return { data: cached };
    }

    // 2️⃣ Not cached → fetch from the real tile server.
    //    Adjust the fallback URL to match your own source.
    const fallbackUrl = `https://my.tileserver.com/tiles/${z}/${x}/${y}.pbf`;

    const response = await fetch(fallbackUrl);
    if (!response.ok) {
      // Propagate the error to MapLibre (it will show a missing-tile placeholder)
      throw new Error(`Network error ${response.status} for ${fallbackUrl}`);
    }
    const arrayBuffer = await response.arrayBuffer();

    // 3️⃣ Store the freshly fetched tile for future use
    // (fire-and-forget – we don’t need to wait for it to finish)
    putTile(z, x, y, arrayBuffer).catch(console.error);

    // 4️⃣ Return the data to MapLibre
    return {
      data: arrayBuffer,
      // Optional HTTP-like metadata – useful for the built-in cache logic
      cacheControl: response.headers.get('Cache-Control') ?? undefined,
      expires: response.headers.get('Expires') ?? undefined,
      etag: response.headers.get('ETag') ?? undefined,
    };
  });
}
```

> **Why the `RequestParametersWithUrl` cast?**  
> The generic `RequestParameters` type does not expose `url` (it’s added by the
> protocol handler). The cast is safe because MapLibre always passes an object
> that contains `url`.

---

## 4️⃣ Put it all together – create the map

```ts
// src/main.ts
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { registerCacheProtocol } from './registerCacheProtocol';

// Register the protocol **before** you instantiate the map
registerCacheProtocol();

const map = new maplibregl.Map({
  container: 'map',               // id of the <div>
  style: {
    version: 8,
    sources: {
      // The source uses the custom scheme.
      // The URL can be absolute (as shown) or relative – MapLibre just passes it
      // straight to the protocol handler.
      myVector: {
        type: 'vector',
        url: 'cache://tiles/{z}/{x}/{y}',
        // If you need a tilejson wrapper you can also use `tiles: [...]`
        // but the `url` shortcut works for the simple pattern above.
      },
    },
    layers: [
      {
        id: 'my-fill',
        type: 'fill',
        source: 'myVector',
        'source-layer': 'my_layer_name', // <-- whatever layer name is inside the MVT
        paint: {
          'fill-color': '#3bb2d0',
          'fill-opacity': 0.6,
        },
      },
    ],
  },
  center: [0, 0],
  zoom: 2,
});
```

**Result:**  
When the map needs a tile, MapLibre calls the `cache://` handler. The handler looks in IndexedDB, returns the cached `ArrayBuffer` if it exists, otherwise fetches the tile from the real server, stores it, and returns it to the renderer. All of this happens **entirely in the browser** – no service-worker or external server is required.

---

## 5️⃣ Quick checklist / gotchas

| ✅ | Item |
|---|------|
| **MapLibre version** | ≥ 4.0.0 (promise-based `addProtocol`). |
| **IndexedDB** | Works in all modern browsers; on iOS Safari you may need to request persistent storage (`navigator.storage.persist()`) if you want the cache to survive a low-memory purge. |
| **CORS** | The fallback network request must be CORS-enabled (or same-origin). The `cache://` scheme itself bypasses CORS because the data never leaves the browser. |
| **Tile format** | The example assumes MapLibre vector tiles (`.pbf`). If you use a different format (e.g., `MVT` with gzip), just store the raw bytes – MapLibre will decode them. |
| **Error handling** | Throwing inside the handler makes MapLibre treat the tile as missing (it will draw a “no-data” placeholder). |
| **Performance tip** | If you expect many concurrent requests, keep the `fetch` fallback **outside** the IndexedDB transaction (as shown) – otherwise the DB can become a bottleneck. |
| **Cleaning the cache** | `await (await getDB()).clear('tiles')` will wipe everything. You can expose a UI button that calls it. |

---

## 6️⃣ Full source (single-file version) – for copy-paste demos

If you don’t want a build step, you can drop everything into a single HTML file that uses the CDN versions of MapLibre GL JS and `idb`. Below is a minimal example you can open directly in a browser:

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>MapLibre + cache:// protocol demo</title>
  <link href="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    body, html { margin:0; height:100%; }
    #map { width:100%; height:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import maplibregl from 'https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.esm.js';
  import { openDB } from 'https://cdn.jsdelivr.net/npm/idb@8/+esm';

  // ---------- IndexedDB helpers ----------
  const DB_NAME = 'maplibre-tile-cache';
  const STORE = 'tiles';
  const dbPromise = openDB(DB_NAME, 1, {
    upgrade(db) { db.createObjectStore(STORE); }
  });

  async function getTile(z, x, y) {
    const db = await dbPromise;
    return db.get(STORE, `${z}/${x}/${y}`);
  }
  async function putTile(z, x, y, data) {
    const db = await dbPromise;
    return db.put(STORE, data, `${z}/${x}/${y}`);
  }

  // ---------- protocol ----------
  function parseCacheUrl(url) {
    const path = url.replace(/^cache:\/\//, '').replace(/^\/+/, '');
    const parts = path.split('/');
    if (parts.length !== 4 || parts[0] !== 'tiles')
      throw new Error('Unexpected cache URL: ' + url);
    const [z, x, y] = parts.slice(1).map(Number);
    return { z, x, y };
  }

  maplibregl.addProtocol('cache', async ({ url }) => {
    const { z, x, y } = parseCacheUrl(url);
    const cached = await getTile(z, x, y);
    if (cached) return { data: cached };

    // fallback – replace with your own tile endpoint
    const fallback = `https://tileserver.example.com/${z}/${x}/${y}.pbf`;
    const resp = await fetch(fallback);
    if (!resp.ok) throw new Error(`Network ${resp.status}`);
    const buf = await resp.arrayBuffer();
    putTile(z, x, y, buf).catch(console.error);
    return { data: buf };
  });

  // ---------- map ----------
  const map = new maplibregl.Map({
    container: 'map',
    style: {
      version: 8,
      sources: {
        myVector: {
          type: 'vector',
          url: 'cache://tiles/{z}/{x}/{y}'
        }
      },
      layers: [{
        id: 'fill',
        type: 'fill',
        source: 'myVector',
        'source-layer': 'my_layer_name',
        paint: { 'fill-color': '#3bb2d0', 'fill-opacity': 0.5 }
      }]
    },
    center: [0, 0],
    zoom: 2
  });
</script>
</body>
</html>
```

