## 4️⃣  Full TypeScript signatures (for reference)

```ts
// maplibre-gl.d.ts (v4+)
declare module 'maplibre-gl' {
  export interface Resource {
    url: string;               // full URL, e.g. "cache://tiles/12/34/56"
    kind: 'Tile' | 'Source' | 'Glyphs' | 'SpriteImage' | 'SpriteJSON' | 'Style';
    // …other fields omitted for brevity
  }

  export interface ResourceResponse {
    data: ArrayBuffer | string | Blob;
    cacheControl?: string;
    expires?: string;
    etag?: string;
    modified?: string;
    // any other HTTP-like headers you want to expose
  }

  /**
   * Register a custom protocol.
   *
   * @param scheme   The scheme name without the colon, e.g. "cache".
   * @param handler  A function that receives the parsed Resource and an AbortController,
   *                 and returns a Promise that resolves to a ResourceResponse.
   */
  export function addProtocol(
    scheme: string,
    handler: (params: Resource, abortCtrl: AbortController) => Promise<ResourceResponse>
  ): void;
}
```

